-- 0049  Babelway, from a channel the group built and called in a trial
--       environment.
--
-- Babelway is one of the thirteen APIs the client designated on 6 October
-- 2026, as a Transformation that can stand where AmitTransform stands. Migration
-- 0040 left it out because it publishes no specification. The client wrote on
-- 11 October: "Babelway also don't has open api spec. It gives 30 days free
-- trial so you can extract important information manually after you test it".
--
-- Babelway has no fixed public API. An environment builds a channel, and a
-- channel whose gateway in is a "REST API Server" publishes an HTTP address
-- that answers each call with the channel's output. On 13 October 2026 the
-- group built one in a trial environment:
--
--   gateway in    REST API Server, body of the call as the message
--   message in    JSON, defined from a sample invoice
--   transform     visual mapping, 60 values and one loop (invoice lines)
--   message out   UBL, defined from a sample UBL 2.1 invoice
--   gateway out   NULL: the result only goes back to the caller
--
-- and called it:
--
--   a test invoice with two lines       200 in about 3 s, a UBL 2.1 invoice;
--                                       ESS SmartDocFlow PINT A-NZ: 3 of 3 pass
--   JSON cut short                      500, error code messageInError
--   after the channel was switched off  404, error code unknownGateway
--
-- The group wrote an OpenAPI document from that channel and those calls
-- (frontend/public/specs/babelway-invoice-json-to-ubl-openapi.json,
-- sha256 386852d092f89f9f9384cf055ec5519860e55a5bbc86306d708acbfba420ac68),
-- and built the rows with the importer's own code, as migrations 0040, 0045
-- and 0048 did.
--
-- Set by hand: the readable name, the website, the instructions and the
-- authentication details.
--
-- Limits, stated in the document and in the record:
--   * The request fields are those of the group's test channel, not a format
--     Babelway prescribes; another channel defines its own.
--   * The identifiers, tax scheme and tax category in the output are constants
--     of the group's mapping, so that the result is a PINT A-NZ invoice.
--   * The endpoint keeps {urlIdentifier} as a placeholder. The test gateway
--     listed no credentials, so its identifier is not stored, and the channel
--     was switched off after the test.
--   * The trial lasts 30 days.
--
-- The new record arrives as Published; an administrator verifies it in the
-- application.

-- ----------------------------------------------------------------- preconditions

create temporary table _0049_api on commit drop as
select * from jsonb_populate_recordset(null::public.apis, $rows0049$[{"api_name":"Babelway Convert Invoice JSON to UBL XML API","official_api_name":"convertInvoiceJsonToUbl","description":"Sends the invoice as JSON to a channel's REST API Server gateway and receives the channel's output, a UBL 2.1 invoice, in the same call. The channel the group built maps each value of the request to its UBL element, repeats the invoice line for each item, and writes the Peppol PINT A-NZ identifiers, the GST tax scheme and tax category S as constants. Babelway also accepts PUT and PATCH, and a path ending in .json, according to its help centre; the group called POST with .xml.","api_endpoint":"https://eu1.babelway.net/rest/{urlIdentifier}/message.xml","company_name":"Babelway","company_name_original":"Babelway","official_company_name":"","documentation_url":"https://babelway.zendesk.com/hc/en-us/articles/15607402778396-4-2-2-14-Rest-Gateway-In","source_url":"https://babelway.zendesk.com/hc/en-us/articles/15607402778396-4-2-2-14-Rest-Gateway-In","http_method":"POST","category":"Transformation","communication_direction":"","authentication_method":"None","authentication_other":"","input_formats":["JSON"],"input_formats_original":["application/json"],"output_formats":["XML"],"output_formats_original":["text/xml"],"data_quality":"ok","access_scope":"public","review_status":"Published","id":"848d937e-f2f1-446f-a050-64c824b3657d","website_url":"https://www.babelway.com","network":"","authentication_details":"None in the group's test: its trial gateway listed no allowed credentials and answered without any. A REST API Server gateway normally lists user name and password pairs, which a caller sends by HTTP Basic authentication or as 'user' and 'password' parameters or headers (Babelway help centre).","instructions":"Babelway has no fixed API: build a channel in a Babelway environment whose gateway in is a REST API Server, and POST the message to https://eu1.babelway.net/rest/{urlIdentifier}/message.xml, where {urlIdentifier} is the identifier set on that gateway. The channel's output comes back in the same call. The request fields recorded here are those of the group's test channel; another channel defines its own."}]$rows0049$::jsonb);

do $$
declare clash integer;
begin
  select count(*) into clash
    from _0049_api new_api
    join public.apis api
      on (lower(api.company_name) = lower(new_api.company_name) and lower(api.api_name) = lower(new_api.api_name))
      or (api.api_endpoint = new_api.api_endpoint and api.http_method = new_api.http_method);
  if clash <> 0 then
    raise exception '0049 precondition failed: the Babelway conversion operation already exists.';
  end if;
end
$$;

